1	use oxc_linter::FixKind;
2	use tower_lsp_server::ls_types::{CodeAction, CodeActionKind, TextEdit, Uri, WorkspaceEdit};
3	use tracing::debug;
4	
5	use crate::lsp::error_with_position::{FixedContent, FixedContentKind, LinterCodeAction};
6	
7	pub const CODE_ACTION_KIND_SOURCE_FIX_ALL_OXC: CodeActionKind =
8	    CodeActionKind::new("source.fixAll.oxc");
9	
10	fn fix_content_to_code_action(
11	    fixed_content: FixedContent,
12	    uri: Uri,
13	    is_preferred: bool,
14	) -> CodeAction {
15	    CodeAction {
16	        title: fixed_content.message,
17	        kind: Some(CodeActionKind::QUICKFIX),
18	        is_preferred: Some(is_preferred),
19	        edit: Some(WorkspaceEdit {
20	            #[expect(clippy::disallowed_types)]
21	            changes: Some(std::collections::HashMap::from([(
22	                uri,
23	                vec![TextEdit { range: fixed_content.range, new_text: fixed_content.code }],
24	            )])),
25	            ..WorkspaceEdit::default()
26	        }),
27	        disabled: None,
28	        data: None,
29	        diagnostics: None,
30	        command: None,
31	    }
32	}
33	
34	pub fn apply_fix_code_actions(action: LinterCodeAction, uri: &Uri) -> Vec<CodeAction> {
35	    let mut code_actions = vec![];
36	
37	    let mut preferred_possible = true;
38	    for fixed in action.fixed_content {
39	        // only rule fixes and unused directive fixes can be preferred, ignore fixes are not preferred.
40	        let preferred = preferred_possible
41	            && matches!(
42	                fixed.lsp_kind,
43	                FixedContentKind::LintRule | FixedContentKind::UnusedDirective
44	            );
45	        if preferred {
46	            // only the first fix can be preferred, if there are multiple fixes available.
47	            preferred_possible = false;
48	        }
49	        let action = fix_content_to_code_action(fixed, uri.clone(), preferred);
50	        code_actions.push(action);
51	    }
52	
53	    code_actions
54	}
55	
56	pub fn apply_all_fix_code_action(
57	    actions: impl Iterator<Item = LinterCodeAction>,
58	    uri: Uri,
59	) -> Option<CodeAction> {
60	    let quick_fixes: Vec<TextEdit> = fix_all_text_edit(actions);
61	
62	    if quick_fixes.is_empty() {
63	        return None;
64	    }
65	
66	    Some(CodeAction {
67	        title: "fix all safe fixable oxlint issues".to_string(),
68	        kind: Some(CODE_ACTION_KIND_SOURCE_FIX_ALL_OXC),
69	        is_preferred: Some(true),
70	        edit: Some(WorkspaceEdit {
71	            #[expect(clippy::disallowed_types)]
72	            changes: Some(std::collections::HashMap::from([(uri, quick_fixes)])),
73	            ..WorkspaceEdit::default()
74	        }),
75	        disabled: None,
76	        data: None,
77	        diagnostics: None,
78	        command: None,
79	    })
80	}
