82	/// Collect all text edits from the provided diagnostic reports, which can be applied at once.
83	/// This is useful for implementing a "fix all" code action / command that applies multiple fixes in one go.
84	pub fn fix_all_text_edit(actions: impl Iterator<Item = LinterCodeAction>) -> Vec<TextEdit> {
85	    let mut text_edits: Vec<TextEdit> = vec![];
86	
87	    for action in actions {
88	        // Applying all possible fixes at once is not possible in this context.
89	        // Search for the first "real" fix for the rule, and ignore the rest of the fixes for the same rule.
90	        let Some(fixed_content) = action.fixed_content.into_iter().find(|fixed| {
91	            matches!(fixed.lsp_kind, FixedContentKind::LintRule | FixedContentKind::UnusedDirective)
92	        }) else {
93	            continue;
94	        };
95	
96	        // Only safe fixes or suggestions are applied in "fix all" action/command.
97	        if !FixKind::SafeFixOrSuggestion.can_apply(fixed_content.kind) {
98	            debug!("Skipping unsafe fix for fix all action: {}", fixed_content.message);
99	            continue;
100	        }
101	
102	        // when source.fixAll.oxc we collect all changes at ones
103	        // and return them as one workspace edit.
104	        // it is possible that one fix will change the range for the next fix
105	        // see oxc-project/oxc#10422
106	        text_edits.push(TextEdit { range: fixed_content.range, new_text: fixed_content.code });
107	    }
108	
109	    text_edits
110	}
