644	        let mut code_actions_vec: Vec<CodeActionOrCommand> = vec![];
645	
646	        for kind in applying_kinds {
647	            // `CODE_ACTION_KIND_SOURCE_FIX_ALL_OXC` was filtered out by `applying_kinds`, so we don't need to check it here.
648	            if kind == CodeActionKind::SOURCE_FIX_ALL {
